export type GetOhlcvData = {
    body?: never;
    path?: never;
    query: {
        /**
         * Mint pubkey
         */
        mint: string;
        /**
         * Timeframe (e.g. 1m, 5m, 1h)
         */
        tf: string;
        /**
         * Market (pool pubkey) to chart; defaults to the mint's default market (lifetime-dominant pool, preferring the currently-active one on a genuine market rotation) — so tokens idle past 24h still chart. The default pool carries is_default on /api/mints/{pubkey}/markets
         */
        pool?: string;
        /**
         * Market scope (lineage|pool). Unpinned: defaults to lineage, which merges a graduated token's bonding curve with the pool it migrated to so it charts as one continuous market; pool reads the single dominant pool. With `pool` set: defaults to pool (that pool verbatim); pass lineage to expand the pinned pool to its own migration lineage — the market a specific fill happened in.
         */
        market?: string;
        /**
         * Price denomination (native|sol|usd; default native)
         */
        quote?: string;
        /**
         * Start of window (RFC3339)
         */
        from?: string;
        /**
         * End of window (RFC3339, exclusive)
         */
        to?: string;
        /**
         * Max candles to return when `from` is omitted (count of candles, gaps ignored; default 500, capped at 5000)
         */
        limit?: number;
        /**
         * Drop clear price-outlier candles at read time (cosmetic; never changes stored data). Default false.
         */
        removeOutliers?: boolean;
    };
    url: '/api/ohlcv';
};

